using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>A four-sided facade panel cut from a surface.</summary>
    public sealed class Panel
    {
        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            Corners = new[] { c0, c1, c2, c3 };
            Index = index;
            Area = 0.5 * Vector3d.CrossProduct(c2 - c0, c3 - c1).Length;
            Deviation = ComputeDeviation(c0, c1, c2, c3);
            double[] e = EdgeLengths;
            Width = (e[0] + e[2]) / 2.0;
            Height = (e[1] + e[3]) / 2.0;
        }

        public Point3d[] Corners { get; }
        public int Index { get; }
        public double Area { get; }
        public double Deviation { get; }
        public double Width { get; }
        public double Height { get; }

        public Point3d Center => new Point3d(
            Corners.Average(p => p.X), Corners.Average(p => p.Y), Corners.Average(p => p.Z));

        public double[] EdgeLengths => new[]
        {
            Corners[0].DistanceTo(Corners[1]), Corners[1].DistanceTo(Corners[2]),
            Corners[2].DistanceTo(Corners[3]), Corners[3].DistanceTo(Corners[0])
        };

        public double[] DiagonalLengths => new[]
        {
            Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3])
        };

        public PolylineCurve Outline =>
            new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });

        private static double ComputeDeviation(Point3d c0, Point3d c1, Point3d c2, Point3d c3)
        {
            Vector3d n = Vector3d.CrossProduct(c1 - c0, c2 - c0);
            if (n.Length > 1e-12)
            {
                n.Unitize();
                return Math.Abs(n * (c3 - c0));
            }
            // Degenerate (collinear) first three corners: distance to their line.
            Vector3d d = c2 - c0;
            if (d.Length < 1e-12) d = c1 - c0;
            if (d.Length < 1e-12) return c0.DistanceTo(c3);
            return new Line(c0, c0 + d).DistanceTo(c3, false);
        }
    }

    public class PanelGoo : GH_Goo<Panel>
    {
        public PanelGoo() { }
        public PanelGoo(Panel panel) : base(panel) { }

        public override bool IsValid => Value != null;
        public override string TypeName => "Panel";
        public override string TypeDescription => "A four-sided facade panel";
        public override IGH_Goo Duplicate() => new PanelGoo(Value);

        public override string ToString() => Value == null
            ? "Null Panel"
            : $"Panel {Value.Index} (area {Value.Area:0.###}, deviation {Value.Deviation:0.###})";
    }

    public class PanelParam : GH_Param<PanelGoo>
    {
        public PanelParam()
            : base("Panel", "Panel", "A facade panel", "Facade", "Panels", GH_ParamAccess.item) { }

        public override Guid ComponentGuid => new Guid("c0a1d6e2-5b3f-4a71-9e08-2d4f6b8a1c01");
        public override GH_Exposure Exposure => GH_Exposure.hidden;
    }

    internal static class PanelIO
    {
        public static List<Panel> GetPanels(IGH_DataAccess da, int index)
        {
            var goos = new List<PanelGoo>();
            da.GetDataList(index, goos);
            return goos.Where(g => g != null && g.Value != null).Select(g => g.Value).ToList();
        }

        public static IEnumerable<PanelGoo> Wrap(IEnumerable<Panel> panels) =>
            panels.Select(p => new PanelGoo(p));
    }
}
