using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize", "Divide a surface into four-sided panels", "Facade", "Panels") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0001-4a10-8f01-a1b2c3d4e501");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to divide", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Panels in U direction", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Panels in V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int u = 10, v = 6;
            if (!DA.GetData(0, ref surface) || surface == null) return;
            DA.GetData(1, ref u);
            DA.GetData(2, ref v);
            if (u < 1 || v < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must be at least 1.");
                return;
            }

            Interval du = surface.Domain(0), dv = surface.Domain(1);
            var pts = new Point3d[u + 1, v + 1];
            for (int i = 0; i <= u; i++)
                for (int j = 0; j <= v; j++)
                    pts[i, j] = surface.PointAt(du.ParameterAt((double)i / u), dv.ParameterAt((double)j / v));

            var panels = new List<Panel>(u * v);
            for (int j = 0; j < v; j++)
                for (int i = 0; i < u; i++)
                    panels.Add(new Panel(pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1], j * u + i));

            DA.SetDataList(0, PanelIO.Wrap(panels));
            DA.SetDataList(1, panels.Select(p => p.Outline));
        }
    }

    public class PanelInfoComponent : GH_Component
    {
        public PanelInfoComponent()
            : base("Panel Info", "PanelInfo", "Deconstruct a panel", "Facade", "Panels") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0002-4a10-8f01-a1b2c3d4e502");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panel", "P", "Panel", GH_ParamAccess.item);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddPointParameter("Corners", "C", "Four corners in order", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outline", "O", "Closed outline", GH_ParamAccess.item);
            pManager.AddNumberParameter("Area", "A", "Panel area", GH_ParamAccess.item);
            pManager.AddPointParameter("Center", "Ce", "Average of the corners", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Index", "I", "Grid index", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            PanelGoo goo = null;
            if (!DA.GetData(0, ref goo) || goo == null || goo.Value == null) return;
            Panel p = goo.Value;
            DA.SetDataList(0, p.Corners);
            DA.SetData(1, p.Outline);
            DA.SetData(2, p.Area);
            DA.SetData(3, p.Center);
            DA.SetData(4, p.Index);
        }
    }

    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Planarity deviation of panels", "Facade", "Analysis") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0003-4a10-8f01-a1b2c3d4e503");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum flat deviation", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Deviation per panel", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "Deviation within tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double tol = 0.5;
            DA.GetData(1, ref tol);

            var dev = panels.Select(p => p.Deviation).ToList();
            var flat = dev.Select(d => d <= tol).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{notFlat} of {panels.Count} panels are not flat.");

            DA.SetDataList(0, dev);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }

    public class ClassifyPanelsComponent : GH_Component
    {
        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify", "Classify panels as flat, cold-bent or custom", "Facade", "Analysis") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0004-4a10-8f01-a1b2c3d4e504");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Flat tolerance", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "T", "flat, cold-bent or custom", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "C", "Cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "U", "Custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double tol = 0.5;
            DA.GetData(1, ref tol);

            var types = panels.Select(p =>
                p.Deviation <= tol ? "flat" : p.Deviation <= 10 * tol ? "cold-bent" : "custom").ToList();
            DA.SetDataList(0, types);
            DA.SetData(1, types.Count(t => t == "flat"));
            DA.SetData(2, types.Count(t => t == "cold-bent"));
            DA.SetData(3, types.Count(t => t == "custom"));
        }
    }

    public class PanelStatsComponent : GH_Component
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Stats", "Area statistics of panels", "Facade", "Analysis") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0005-4a10-8f01-a1b2c3d4e505");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "T", "Sum of areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Average area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "No panels supplied.");
                return;
            }
            var areas = panels.Select(p => p.Area).ToList();
            DA.SetData(0, areas.Sum());
            DA.SetData(1, areas.Min());
            DA.SetData(2, areas.Max());
            DA.SetData(3, areas.Average());
        }
    }
}
