using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Group panels with matching dimensions", "Facade", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0006-4a10-8f01-a1b2c3d4e506");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Length tolerance", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        private static double[] Signature(Panel p)
        {
            var e = p.EdgeLengths; Array.Sort(e);
            var d = p.DiagonalLengths; Array.Sort(d);
            return e.Concat(d).ToArray();
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double tol = 1.0;
            DA.GetData(1, ref tol);

            var sigs = new List<double[]>();
            var reps = new List<Panel>();
            var groups = new List<int>();
            foreach (var p in panels)
            {
                var s = Signature(p);
                int g = sigs.FindIndex(r => r.Zip(s, (a, b) => Math.Abs(a - b) <= tol).All(x => x));
                if (g < 0)
                {
                    sigs.Add(s);
                    reps.Add(p);
                    g = sigs.Count - 1;
                }
                groups.Add(g);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, PanelIO.Wrap(reps));
        }
    }

    public class NestOnSheetsComponent : GH_Component
    {
        private sealed class Placement
        {
            public int Order, Sheet;
            public double X, Y, W, H;
        }

        private sealed class NestResult
        {
            public List<Placement> Placed;
            public int SheetCount, Unplaced;
            public double Utilization;
        }

        private CancellationTokenSource _cts;
        private double[] _runningInput;
        private double[] _doneInput;
        private NestResult _result;
        private volatile int _progress;
        private int _total;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nest panels as rectangles on sheets (shelf algorithm)", "Facade", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0007-4a10-8f01-a1b2c3d4e507");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Placed rectangles", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area / total sheet area", GH_ParamAccess.item);
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            Cancel();
            base.RemovedFromDocument(document);
        }

        private void Cancel()
        {
            if (_cts != null) { _cts.Cancel(); _cts = null; }
            _runningInput = null;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double w = 3000, h = 1500, spacing = 10;
            DA.GetData(1, ref w);
            DA.GetData(2, ref h);
            DA.GetData(3, ref spacing);
            if (w <= 0 || h <= 0 || spacing < 0)
            {
                Cancel();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet size must be positive and spacing not negative.");
                return;
            }

            var input = new List<double> { w, h, spacing };
            foreach (var p in panels) { input.Add(p.Width); input.Add(p.Height); }
            double[] key = input.ToArray();

            if (_result != null && _doneInput != null && _doneInput.SequenceEqual(key))
            {
                Message = "";
                Output(DA, _result, w, h);
                return;
            }

            if (_runningInput == null || !_runningInput.SequenceEqual(key))
            {
                Cancel();
                var cts = new CancellationTokenSource();
                _cts = cts;
                _runningInput = key;
                _progress = 0;
                _total = panels.Count;
                var rects = panels.Select(p => (p.Width, p.Height)).ToList();
                Task.Run(() =>
                {
                    try
                    {
                        var res = Nest(rects, w, h, spacing, cts.Token);
                        if (cts.IsCancellationRequested) return;
                        _result = res;
                        _doneInput = key;
                        _runningInput = null;
                        Rhino.RhinoApp.InvokeOnUiThread(new Action(() =>
                        {
                            if (cts.IsCancellationRequested) return;
                            ExpireSolution(true);
                        }));
                    }
                    catch (OperationCanceledException) { }
                });
            }

            Message = _total > 0 ? $"Nesting {_progress}/{_total}" : "Nesting...";
            // Do not wait: the finished run re-triggers the solution.
            ScheduleProgressRefresh();
        }

        private void ScheduleProgressRefresh()
        {
            var cts = _cts;
            if (cts == null) return;
            Task.Delay(300).ContinueWith(_ =>
            {
                if (cts.IsCancellationRequested || _runningInput == null) return;
                Rhino.RhinoApp.InvokeOnUiThread(new Action(() =>
                {
                    if (cts.IsCancellationRequested || _runningInput == null) return;
                    Message = $"Nesting {_progress}/{_total}";
                    OnDisplayExpired(false);
                    ScheduleProgressRefresh();
                }));
            });
        }

        private void Output(IGH_DataAccess DA, NestResult r, double w, double h)
        {
            if (r.Unplaced > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{r.Unplaced} panel(s) do not fit on any sheet.");
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            foreach (var p in r.Placed)
            {
                double ox = p.Sheet * (w + 100.0) + p.X;
                var a = new Point3d(ox, p.Y, 0);
                var b = new Point3d(ox + p.W, p.Y, 0);
                var c = new Point3d(ox + p.W, p.Y + p.H, 0);
                var d = new Point3d(ox, p.Y + p.H, 0);
                outlines.Add(new PolylineCurve(new[] { a, b, c, d, a }));
                sheets.Add(p.Sheet);
            }
            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, r.SheetCount);
            DA.SetData(3, r.Utilization);
        }

        private NestResult Nest(List<(double W, double H)> rects, double sw, double sh, double sp, CancellationToken ct)
        {
            var order = Enumerable.Range(0, rects.Count).OrderByDescending(i => rects[i].H).ThenBy(i => i).ToList();
            var placed = new List<Placement>();
            int unplaced = 0;
            int sheet = 0;
            bool sheetOpen = false;
            double shelfY = sp, shelfH = 0, x = sp;
            bool shelfOpen = false;
            int done = 0;

            bool FitsEmptySheet(double pw, double ph) => sp + pw <= sw - sp && sp + ph <= sh - sp;

            foreach (int i in order)
            {
                ct.ThrowIfCancellationRequested();
                _progress = ++done;
                var (pw, ph) = rects[i];

                if (!FitsEmptySheet(pw, ph) && !FitsEmptySheet(ph, pw)) { unplaced++; continue; }

                Placement pl = null;

                // 1. current shelf
                if (shelfOpen)
                {
                    if (x + pw <= sw - sp && ph <= shelfH) pl = Make(i, sheet, x, shelfY, pw, ph);
                    else if (x + ph <= sw - sp && pw <= shelfH) pl = Make(i, sheet, x, shelfY, ph, pw);
                }
                // 2. new shelf on current sheet
                if (pl == null && sheetOpen)
                {
                    double ny = shelfY + shelfH + sp;
                    if (sp + pw <= sw - sp && ny + ph <= sh - sp) pl = Start(i, sheet, ny, pw, ph);
                    else if (sp + ph <= sw - sp && ny + pw <= sh - sp) pl = Start(i, sheet, ny, ph, pw);
                }
                // 3. new sheet
                if (pl == null)
                {
                    sheet = sheetOpen ? sheet + 1 : 0;
                    sheetOpen = true;
                    if (sp + pw <= sw - sp && sp + ph <= sh - sp) pl = Start(i, sheet, sp, pw, ph);
                    else pl = Start(i, sheet, sp, ph, pw);
                }
                placed.Add(pl);
                x = pl.X + pl.W + sp;
            }

            Placement Make(int idx, int s, double px, double py, double pw2, double ph2) =>
                new Placement { Order = idx, Sheet = s, X = px, Y = py, W = pw2, H = ph2 };

            Placement Start(int idx, int s, double ny, double pw2, double ph2)
            {
                shelfOpen = true;
