                new Placement { Order = idx, Sheet = s, X = px, Y = py, W = pw2, H = ph2 };

            Placement Start(int idx, int s, double ny, double pw2, double ph2)
            {
                shelfOpen = true;
                shelfY = ny;
                shelfH = ph2;
                return Make(idx, s, sp, ny, pw2, ph2);
            }

            placed = placed.OrderBy(p => p.Order).ToList();
            int sheetCount = sheetOpen ? sheet + 1 : 0;
            double util = sheetCount == 0 ? 0 : placed.Sum(p => p.W * p.H) / (sheetCount * sw * sh);
            return new NestResult { Placed = placed, SheetCount = sheetCount, Unplaced = unplaced, Utilization = util };
        }
    }

    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "CutList", "CSV cut list of panels", "Facade", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("1b2c3d4e-0008-4a10-8f01-a1b2c3d4e508");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "Path", "CSV file path", GH_ParamAccess.item, "");
            pManager.AddBooleanParameter("Write", "W", "Write the file", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "W", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("index,width,height,area,deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("0.###", inv)).Append(',')
                  .Append(p.Height.ToString("0.###", inv)).Append(',')
                  .Append(p.Area.ToString("0.###", inv)).Append(',')
                  .Append(p.Deviation.ToString("0.###", inv)).Append('\n');
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                else
                {
                    try { File.WriteAllText(path, csv); written = true; }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + ex.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}

